// ─── 1. Extrair dados do webhook ───────────────────────────────────────────
const wh = $input.first().json;
const body = (wh.application_id !== undefined) ? wh : (wh.body || wh);

const appId      = body.application_id;
const callbackUrl = body.callback_url;

if (!appId || !callbackUrl) {
  throw new Error('Dados em falta: application_id=' + appId + ' callback_url=' + callbackUrl);
}

const skills      = String(body.candidate_skills     || '').slice(0, 2000);
const summary     = String(body.candidate_summary    || '').slice(0, 1000);
const experience  = String(body.candidate_experience || '').slice(0, 2000);
const jobTitle    = String(body.job_title            || '');
const requirements = String(body.job_requirements   || '').slice(0, 3000);

// ─── 2. Construir prompt ────────────────────────────────────────────────────
const prompt =
  'Compara o candidato com a vaga. Responde APENAS com JSON valido com dois campos: ' +
  'similarity_score (inteiro 0-100) e match_feedback (string).\n\n' +
  'Candidato — Skills: ' + skills + ' | Resumo: ' + summary + ' | Experiencia: ' + experience + '\n' +
  'Vaga: ' + jobTitle + ' | Requisitos: ' + requirements;

// ─── 3. Chamar Ollama (stream DEVE ser boolean false) ──────────────────────
const ollamaResp = await $helpers.httpRequest({
  method: 'POST',
  url: 'http://127.0.0.1:11434/api/generate',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ model: 'llama3.2:1b', stream: false, format: 'json', prompt }),
  returnFullResponse: false
});

// ─── 4. Interpretar resposta do Ollama ──────────────────────────────────────
let result = {};
try {
  const raw = String(
    (typeof ollamaResp === 'string' ? ollamaResp : null) ||
    (ollamaResp && ollamaResp.response) ||
    '{}'
  );
  const cleaned = raw.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
  result = JSON.parse(cleaned);
} catch (_) {
  result = {};
}

const similarityScore = Math.min(100, Math.max(0, parseFloat(result.similarity_score) || 0));
const matchFeedback   = String(result.match_feedback || 'Analise nao disponivel.').trim();

// ─── 5. Callback para o Django ──────────────────────────────────────────────
await $helpers.httpRequest({
  method: 'POST',
  url: callbackUrl,
  headers: {
    'Content-Type': 'application/json',
    'X-Kubuka-Secret': 'kubuka-secret-token-2025'
  },
  body: JSON.stringify({ similarity_score: similarityScore, match_feedback: matchFeedback }),
  returnFullResponse: false
});

return [{ json: { success: true, application_id: appId, similarity_score: similarityScore } }];
